extern "C" char* strncpy(char*, const char*, unsigned int);
extern "C" char* strlwr(char*);

typedef unsigned long u_long;

class nglFixedString
{
public:
  typedef u_long fint;
  enum { STR_SIZE = 32, NUM_FINTS = 4 };

  fint* value() { return reinterpret_cast<fint*>(str); }
  const fint* value() const { return reinterpret_cast<const fint*>(str); }

  nglFixedString(const char* s)
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      value()[i] = 0;

    strncpy(str, s, STR_SIZE - 1);
    strlwr(str);
  }

  bool operator==(const nglFixedString& rhs) const
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      if (!(value()[i] == rhs.value()[i]))
        return false;
    return true;
  }

private:
  char str[STR_SIZE];
};

class nglInstanceBank
{
public:
  struct Instance
  {
    nglFixedString Key;
    void* Value;
    int RefCount;
    Instance* Forward[1];
  };

  Instance* NIL;
  Instance* Head;
};

struct nglMeshFile
{
  nglFixedString FileName;
};

extern nglInstanceBank nglMeshFileBank;
void nglReleaseMeshFile(const nglFixedString& FileName);

void nglReleaseAllMeshFiles()
{
  nglInstanceBank::Instance* Inst = nglMeshFileBank.Head->Forward[0];
  while ( Inst != nglMeshFileBank.NIL )
  {
    if ( ( (nglMeshFile*)Inst->Value )->FileName == nglFixedString( "nglsphere" ) || ( (nglMeshFile*)Inst->Value )->FileName == nglFixedString( "nglradius" ) )
      Inst = Inst->Forward[0];
    else
    {
      Inst->RefCount = 1;
      nglReleaseMeshFile( ( (nglMeshFile*)Inst->Value )->FileName );
      Inst = nglMeshFileBank.Head->Forward[0];
    }
  }
}
